with ranked as (select * from (select *, row_number() over (partition by order_id order by delivered_date desc, id) as latest_rank from shipments) t where latest_rank = 1) select date_trunc('quarter', delivered_date) as quarter_start, order_id, approx_percentile(cost, array(0.25, 0.5, 0.75)) as cost_quartiles, approx_percentile(cost, 0.9) as cost_p90, stddev_samp(cost) as cost_stddev, approx_percentile(cost, 0.5) as cost_p50 from ranked group by quarter_start, order_id having approx_percentile(cost, 0.5) > 0;
